function getRandomItemsWithMusthave(r,e){if(!Array.isArray(r))throw new TypeError("第一个参数必须是数组");if(!Number.isInteger(e)||e<0)throw new TypeError("第二个参数必须是非负整数");if(0===r.length||0===e)return[];const t=r.filter(r=>!0===r.musthave),n=r.filter(r=>!0!==r.musthave);if(t.length>=e)return shuffleArray([...t]).slice(0,e);const f=[...t],o=e-t.length;if(n.length<=o)return f.push(...shuffleArray([...n])),f;const h=shuffleArray([...n]);return f.push(...h.slice(0,o)),f}function getRandomItems(r,e){if(!Array.isArray(r))throw new TypeError("第一个参数必须是数组");if(!Number.isInteger(e)||e<0)throw new TypeError("第二个参数必须是非负整数");if(0===r.length||0===e)return[];if(e>=r.length)return shuffleArray([...r]);const t=[...r];for(let r=t.length-1;r>0;r--){const e=Math.floor(Math.random()*(r+1));[t[r],t[e]]=[t[e],t[r]]}return t.slice(0,e)}function shuffleArray(r){for(let e=r.length-1;e>0;e--){const t=Math.floor(Math.random()*(e+1));[r[e],r[t]]=[r[t],r[e]]}return r}function rangeStep(r,e,t){for(var n=[],f=r;f<=e;f+=t)n.push(f);return n}